# 毕业设计 Step6: API 接口契约设计
contracts = [
    {
        "endpoint": "POST /documents",
        "request": "multipart/form-data: file (PDF/MD)",
        "response_200": {"doc_id": "d001", "filename": "a.pdf", "chunks": 42},
        "error": {"error": {"code": "UNSUPPORTED_TYPE", "message": "仅支持 PDF/Markdown"}},
    },
    {
        "endpoint": "GET /documents",
        "request": "无",
        "response_200": {"documents": [{"doc_id": "d001", "filename": "a.pdf", "page_count": 12}]},
        "error": None,
    },
    {
        "endpoint": "DELETE /documents/{doc_id}",
        "request": "路径参数 doc_id",
        "response_200": {"deleted_chunks": 42},
        "error": {"error": {"code": "DOC_NOT_FOUND", "message": "文档不存在"}},
    },
    {
        "endpoint": "POST /questions",
        "request": {"question": "什么是注意力机制?", "top_k": 3},
        "response_200": {
            "answer": "注意力机制是...[1]",
            "citations": [{"doc_id": "d001", "page": 3, "snippet": "注意力机制允许..."}],
        },
        "error": {"error": {"code": "EMPTY_KB", "message": "知识库为空, 请先上传文档"}},
    },
]

for c in contracts:
    print(f"## {c['endpoint']}")
    print(f"  请求: {c['request']}")
    print(f"  200:  {c['response_200']}")
    if c["error"]:
        print(f"  错误: {c['error']}")
    print()
